    const key = await subtle.importKey("raw", bytes("Jefe"), algorithm, true, ["sign", "verify"]);
    const data = bytes("what do ya want for nothing?");
    const mac = await subtle.sign("HMAC", key, data);
    equal(hex(mac), V.hmac, "mac");
    equal(await subtle.verify("HMAC", key, mac, data), true, "mac verifies");
    equal(await subtle.verify("HMAC", key, mac, tampered), false, "tampered verifies");
